<?php
namespace Tests\Feature;
use App\Models\PosCounter; use App\Models\Product; use App\Models\User; use App\Services\EnterprisePosService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class EnterprisePosTest extends TestCase { use RefreshDatabase; public function test_shift_split_payment_and_cash_expectation():void { $user=User::factory()->create(['is_active'=>true]); $counter=PosCounter::create(['name'=>'Main','code'=>'MAIN','is_active'=>true]); $product=Product::factory()->create(['price'=>100,'discount_price'=>null,'stock_quantity'=>10,'status'=>true]); $this->actingAs($user); $service=app(EnterprisePosService::class); $shift=$service->openShift(['counter_id'=>$counter->id,'opening_cash'=>500]); $sale=$service->checkout(['items'=>[['product_id'=>$product->id,'quantity'=>2]],'discount'=>0,'tax'=>0,'shipping'=>0,'payments'=>[['method'=>'Cash','amount'=>100],['method'=>'Card','amount'=>100]]]); $this->assertDatabaseHas('sale_payments',['sale_id'=>$sale->id,'method'=>'Cash','amount'=>100]); $this->assertDatabaseHas('sale_payments',['sale_id'=>$sale->id,'method'=>'Card','amount'=>100]); $this->assertSame(600.0,$service->expectedCash($shift)); $this->assertSame(8,$product->fresh()->stock_quantity); } public function test_sale_can_be_held_without_reducing_stock():void { $user=User::factory()->create(['is_active'=>true]); $counter=PosCounter::create(['name'=>'Main','code'=>'MAIN','is_active'=>true]); $product=Product::factory()->create(['price'=>50,'stock_quantity'=>5,'status'=>true]); $this->actingAs($user); $service=app(EnterprisePosService::class); $service->openShift(['counter_id'=>$counter->id,'opening_cash'=>0]); $hold=$service->hold(['items'=>[['product_id'=>$product->id,'quantity'=>2]]]); $this->assertSame('held',$hold->status); $this->assertSame(5,$product->fresh()->stock_quantity); } }
